//! The Windows adapters: WASAPI, Win32 (popups, hotkeys, Raw Input, session notifications) and tray-icon. All of the
//! daemon's COM and Win32 calls live under here.

#![expect(unsafe_code, reason = "moving the calling thread to the input desktop is raw Win32")]

pub mod audio;
pub mod desktop;
pub mod input_hardware;
mod policy_config;
pub mod remote_api;
pub mod shortcuts;
pub mod tray;

/// Magic `dwExtraInfo` tag placed on `SendInput` events generated by Cranked Audio so our own low-level keyboard
/// hook never intercepts synthetic media keys we sent ourselves.
pub const CRANKED_EXTRA_INFO: usize = 0x4352_4E4B;

#[link(name = "user32")]
extern "system" {
    fn OpenInputDesktop(dwFlags: u32, fInherit: i32, dwDesiredAccess: u32) -> *mut core::ffi::c_void;
    fn SetThreadDesktop(hDesktop: *mut core::ffi::c_void) -> i32;
    fn CloseDesktop(hDesktop: *mut core::ffi::c_void) -> i32;
}

/// Attaches the calling thread (before it creates any windows or hooks) to the active interactive input desktop
/// (`WinSta0\Default`), so hooks, OSD windows, hotkeys, and tray icons always land on the user's real desktop even if
/// the daemon was spawned from a background or sandboxed desktop.
pub fn attach_input_desktop() {
    const GENERIC_ALL: u32 = 0x1000_0000;
    // SAFETY: plain flags; the handle is checked and closed below
    let desk = unsafe { OpenInputDesktop(0, 0, GENERIC_ALL) };
    if !desk.is_null() {
        // SAFETY: the desktop handle opened above (this thread has no windows or hooks yet)
        let _ = unsafe { SetThreadDesktop(desk) };
        // SAFETY: the same handle, not used again (the thread keeps the desktop it was set to)
        let _ = unsafe { CloseDesktop(desk) };
    }
}
